<script setup lang="ts">
import { computed, ref, toRef, watch } from 'vue';
import { Copy, Globe2, Layers3, Pause, Pencil, Play, Plus, Search, Server, Trash2 } from 'lucide-vue-next';
import AccountUsage from '../AccountUsage.vue';
import { useConsole } from '../composables/useConsole';
import { useTable } from '../composables/useTable';
import { countText, dateText } from '../utils/format';
const workspace = useConsole();
const table = useTable(toRef(workspace, 'filteredUpstreams'));
const all = ref<HTMLInputElement>();
const statusLabels: Record<string, string> = { ready: '就绪', untested: '待测试', disabled: '已停用', credential_error: '凭据异常', cooling: '冷却中', saturated: '并发已满', healthy: '健康', unknown: '未测试', degraded: '需关注' };
const checked = computed(() => !!workspace.filteredUpstreams.length && workspace.selected.length === workspace.filteredUpstreams.length);
watch([() => workspace.selected.length, () => workspace.filteredUpstreams.length], () => { if (all.value) all.value.indeterminate = workspace.selected.length > 0 && !checked.value; });
</script>
<template>
  <div class="info-strip"><Layers3 :size="18" /><span>数值较小的优先级先调度，同层按在途负载与权重分配；代理出口地区可单独检测，模型可用性仍以上游账号测试为准。</span></div>
  <section class="panel table-panel"><div class="table-toolbar"><div class="search-input"><Search :size="17" /><input v-model="workspace.search" aria-label="搜索上游账号" placeholder="搜索账号名称、备注…" /></div><select v-model="workspace.groupFilter" aria-label="筛选账号分组"><option value="">全部分组</option><option v-for="group in workspace.groups" :key="group.id" :value="group.id">{{ group.name }}</option></select><div v-if="workspace.selected.length" class="batch-actions"><span>已选 {{ workspace.selected.length }}</span><button class="text-button" :disabled="!!workspace.busy" @click="workspace.batch(true)">启用</button><button class="text-button" :disabled="!!workspace.busy" @click="workspace.batch(false)">停用</button></div><span v-else class="muted">{{ workspace.filteredUpstreams.length }} / {{ workspace.upstreams.length }} 个账号</span></div>
    <div class="table-scroll"><table><thead><tr><th class="checkbox-cell" scope="col"><input ref="all" type="checkbox" aria-label="选择全部账号" :checked="checked" @change="workspace.toggleAll" /></th><th scope="col"><button class="text-button" @click="table.sortBy('name')">账号</button></th><th scope="col"><button class="text-button" @click="table.sortBy('scheduling')">调度 / 健康</button></th><th scope="col"><button class="text-button" @click="table.sortBy('priority')">优先级 / 权重</button></th><th scope="col">并发负载</th><th scope="col"><button class="text-button" @click="table.sortBy('requests')">请求统计</button></th><th scope="col"><button class="text-button" @click="table.sortBy('last_test_at')">最近测试</button></th><th class="align-right" scope="col">操作</th></tr></thead><tbody><tr v-for="row in table.rows" :key="row.id"><td><input v-model="workspace.selected" type="checkbox" :value="row.id" :aria-label="`选择 ${row.name}`" /></td><td><div class="entity-name"><span class="entity-avatar"><Server :size="17" /></span><div><strong>{{ row.name }}</strong><small class="row-note">分组 · {{ workspace.groupName(row.group_id) }}</small><small class="mono">{{ row.credential_prefix }} <button class="text-button" @click="workspace.copyText(row.id)">复制 ID</button></small><small v-if="row.proxy_label" class="row-note">代理 · {{ row.proxy_label }}</small><small v-if="row.proxy_probe?.success" class="row-note">出口 {{ row.proxy_probe.exit_ip }} · {{ row.proxy_probe.country_code || '地区未知' }}{{ row.proxy_probe.region ? ' / ' + row.proxy_probe.region : '' }} · {{ row.proxy_probe.latency_ms }} ms</small><small v-else-if="row.proxy_probe" class="row-note">出口检测失败</small><small v-if="row.notes" class="row-note">{{ row.notes }}</small></div></div></td><td><span :class="['pill', row.scheduling]"><span class="status-dot" />{{ statusLabels[row.scheduling] }}</span><small class="cell-sub">{{ statusLabels[row.health] }}{{ row.cooldown_until > Date.now() ? ' · ' + Math.ceil((row.cooldown_until - Date.now()) / 1000) + 's' : '' }}</small></td><td><span class="metric-pair">P{{ row.priority }} <span>/ {{ row.load_factor }}×</span></span></td><td><span class="mono">{{ row.inflight }} <span class="muted">/ {{ row.max_concurrency }}</span></span><progress class="load-progress" :value="row.inflight" :max="row.max_concurrency" /></td><td><strong class="number">{{ countText(row.requests) }}</strong><small class="cell-sub">成功 {{ row.successes }} · 失败 {{ row.errors }}</small></td><td><span class="small">{{ dateText(row.last_test_at) }}</span><small class="cell-sub">{{ row.latency_ms === null ? '—' : row.latency_ms + ' ms' }}</small></td><td><div class="row-actions"><button v-if="row.proxy_label" class="icon-button" :disabled="workspace.busy === `proxy:${row.id}`" :aria-label="`检测 ${row.name} 代理出口`" title="检测代理出口 IP 与地区" @click="workspace.checkProxy(row)"><Globe2 :size="16" /></button><button class="icon-button" :aria-label="`复制 ${row.name} 凭据前缀`" title="复制凭据前缀" @click="workspace.copyText(row.credential_prefix)"><Copy :size="16" /></button><button class="icon-button" :aria-label="`测试 ${row.name}`" title="测试账号" @click="workspace.selectAccount(row.id, 'test')"><Play :size="16" /></button><button class="icon-button" :aria-label="`编辑 ${row.name}`" title="编辑账号" @click="workspace.editor = { kind: 'upstreams', item: row }"><Pencil :size="16" /></button><button class="icon-button" :disabled="workspace.busy === row.id" :aria-label="`${row.enabled ? '停用' : '启用'} ${row.name}`" :title="row.enabled ? '停用' : '启用'" @click="workspace.toggle('upstreams', row)"><Pause v-if="row.enabled" :size="16" /><Play v-else :size="16" /></button><button class="icon-button danger" :aria-label="`删除 ${row.name}`" title="删除账号" @click="workspace.confirmation = { kind: 'upstreams', id: row.id, name: row.name, action: 'delete' }"><Trash2 :size="16" /></button></div></td></tr></tbody></table></div>
    <footer v-if="table.pages > 1" class="table-footer"><span>第 {{ table.page }} / {{ table.pages }} 页</span><span><button class="text-button" :disabled="table.page === 1" @click="table.page--">上一页</button><button class="text-button" :disabled="table.page === table.pages" @click="table.page++">下一页</button></span></footer>
    <div v-if="!workspace.filteredUpstreams.length" class="empty-state"><Server :size="32" /><h3>{{ workspace.search ? '没有找到匹配账号' : workspace.groupFilter ? '此分组暂无上游账号' : '连接你的第一个上游账号' }}</h3><p>添加账号后，刷新模型目录即可验证连接。</p><button v-if="!workspace.search" class="button secondary" @click="workspace.editor = { kind: 'upstreams' }"><Plus :size="16" />添加上游账号</button></div>
  </section>
  <div class="usage-grid"><AccountUsage v-for="row in workspace.filteredUpstreams" :key="row.id" :account="row" @updated="workspace.reload(true)" /></div>
</template>
